{"content": "1|/*
2|  TWINTHOS — DARK ARCHITECTURAL
3|  Black. White type. One signal green.
4|  Built as a serious industrial mark, not a SaaS template.
5|*/
6|
7|/* ============================================
8|   DESIGN TOKENS — DARK ARCHITECTURAL
9|   ============================================ */
10|
11|:root {
12|  /* Colours */
13|  --bg: #000000;
14|  --surface: #0a0a0a;
15|  --surface-raised: #111111;
16|  --border: rgba(167,171,176,0.12);
17|  --border-strong: rgba(167,171,176,0.22);
18|
19|  /* Text */
20|  --text: #ffffff;
21|  --text-secondary: #9a9a9a;
22|  --text-tertiary: #6b6b6b;
23|
24|  /* Signal green — operating light */
25|  --signal: #20F782;
26|  --signal-bright: #39FF88;
27|  --signal-dim: rgba(32,247,130,0.15);
28|  --signal-border: rgba(32,247,130,0.3);
29|
30|  /* Titanium — mark metallic */
31|  --titanium: #8a8d91;
32|  --dark-titanium: #4a4d51;
33|
34|  /* Error */
35|  --error: #FF5C5C;
36|
37|  /* Typography */
38|  --text-xs: 12px;
39|  --text-sm: 14px;
40|  --text-base: 20px;
41|  --text-lg: 21px;
42|  --headline-sm: 32px;
43|  --headline-md: 48px;
44|  --headline-lg: 64px;
45|  --headline-xl: 80px;
46|  --headline-xxl: 88px;
47|  --display: clamp(64px, 9vw, 110px);
48|
49|  /* Spacing */
50|  --s1: 8px;
51|  --s2: 16px;
52|  --s3: 24px;
53|  --s4: 32px;
54|  --s5: 48px;
55|  --s6: 56px;
56|  --s8: 64px;
57|  --s10: 80px;
58|  --s12: 96px;
59|  --s16: 120px;
60|  --s20: 160px;
61|  --s24: 220px;
62|
63|  /* Radius */
64|  --r-sm: 2px;
65|  --r-md: 4px;
66|  --r-lg: 6px;
67|
68|  /* Layout */
69|  --max-w: 1320px;
70|  --nav-h: 56px;
71|
72|  /* Motion */
73|  --ease: cubic-bezier(0.4, 0, 0.2, 1);
74|  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
75|  --speed: 200ms;
76|  --speed-fast: 120ms;
77|}
78|
79|/* ============================================
80|   RESET & BASE
81|   ============================================ */
82|
83|*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
84|
85|html { font-size: 16px; -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
86|
87|body {
88|  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
89|  background: var(--bg);
90|  color: var(--text);
91|  font-size: var(--text-base);
92|  line-height: 1.6;
93|  -webkit-font-smoothing: antialiased;
94|  -moz-osx-font-smoothing: grayscale;
95|  text-rendering: optimizeLegibility;
96|  overflow-x: hidden;
97|}
98|
99|/* ============================================
100|   SELECTION & FOCUS
101|   ============================================ */
102|
103|::selection { background: rgba(32,247,130,0.2); color: var(--text); }
104|
105|:focus-visible { outline: 1px solid var(--signal); outline-offset: 3px; }
106|
107|::-webkit-scrollbar { width: 4px; height: 4px; }
108|::-webkit-scrollbar-track { background: transparent; }
109|::-webkit-scrollbar-thumb { background: rgba(167,171,176,0.25); }
110|
111|/* ============================================
112|   LAYOUT
113|   ============================================ */
114|
115|.wrap { max-width: var(--max-w); margin: 0 auto; padding: 0 var(--s5); }
116|
117|/* ============================================
118|   TYPOGRAPHY
119|   ============================================ */
120|
121|h1, h2, h3 {
122|  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
123|  font-weight: 400;
124|  letter-spacing: -0.03em;
125|  line-height: 1.05;
126|  color: var(--text);
127|}
128|
129|.btn-sm {
130|  display: inline-flex;
131|  align-items: center;
132|  justify-content: center;
133|  height: 36px;
134|  padding: 0 var(--s4);
135|  font-size: var(--text-xs);
136|  font-weight: 500;
137|  letter-spacing: -0.01em;
138|  color: var(--text);
139|  text-decoration: none;
140|  border-radius: 0;
141|  transition: color var(--speed) var(--ease), background var(--speed) var(--ease);
142|}
143|
144|.btn-sm:hover { color: var(--text-bright); }
145|
146|.btn-sm.btn-ghost {
147|  background: transparent;
148|  border: 1px solid var(--border-strong);
149|}
150|
151|.btn-sm.btn-ghost:hover {
152|  background: var(--surface);
153|  color: var(--text);
154|}
155|
156|.btn-sm.btn-ghost:active { transform: scale(0.985); }
157|
158|.p-brand {
159|  font-size: var(--text-xs);
160|  color: var(--text-tertiary);
161|  letter-spacing: 0.04em;
162|  text-transform: uppercase;
163|  margin-top: 2px;
164|}
165|
166|.p-brand + .p-brand { margin-top: 0; }
167|
168|/* ============================================
169|   NAVIGATION
170|   ============================================ */
171|
172|.nav {
173|  position: sticky;
174|  top: 0;
175|  z-index: 100;
176|  height: var(--nav-h);
177|  background: rgba(0,0,0,0.95);
178|  border-bottom: 1px solid var(--border);
179|}
180|
181|.nav-inner {
182|  max-width: var(--max-w);
183|  margin: 0 auto;
184|  padding: 0 var(--s5);
185|  height: 100%;
186|  display: flex;
187|  align-items: center;
188|  justify-content: space-between;
189|  gap: var(--s4);
190|}
191|
192|.brand {
193|  display: flex;
194|  align-items: center;
195|  text-decoration: none;
196|}
197|
198|.brand-mark {
199|  width: 24px;
200|  height: 24px;
201|  flex-shrink: 0;
202|}
203|
204|.nav-links { display: flex; align-items: center; gap: var(--s4); }
205|
206|.nav-links a {
207|  color: var(--text-secondary);
208|  text-decoration: none;
209|  font-size: var(--text-sm);
210|  font-weight: 400;
211|  letter-spacing: -0.01em;
212|  transition: color var(--speed) var(--ease);
213|}
214|
215|.nav-links a:hover { color: var(--text); }
216|
217|.nav-links a:focus-visible {
218|  outline: none;
219|  color: var(--text);
220|  border-bottom: 1px solid var(--signal);
221|  padding-bottom: 1px;
222|}
223|
224|.nav-cta:focus-visible {
225|  outline: none;
226|  color: var(--signal);
227|  text-decoration: underline;
228|  text-underline-offset: 3px;
229|}
230|
231|.nav-cta {
232|  display: inline-flex;
233|  align-items: center;
234|  text-decoration: none;
235|  color: var(--text-secondary);
236|  font-size: var(--text-sm);
237|  font-weight: 400;
238|  letter-spacing: -0.01em;
239|  transition: color var(--speed) var(--ease);
240|}
241|
242|.nav-cta::after {
243|  content: '→';
244|  margin-left: 4px;
245|  font-size: calc(var(--text-sm) - 2px);
246|  opacity: 0.5;
247|  transition: opacity var(--speed) var(--ease), transform var(--speed-fast) var(--ease);
248|}
249|
250|.nav-cta:hover {
251|  color: var(--signal);
252|}
253|
254|.nav-cta:hover::after {
255|  opacity: 1;
256|  transform: translateX(2px);
257|}
258|
259|.nav-cta:active {
260|  color: var(--text);
261|}
262|
263|.nav-cta:active::after {
264|  opacity: 0.5;
265|  transform: translateX(0);
266|}
267|
268|.nav-burger {
269|  display: none;
270|  width: 36px;
271|  height: 36px;
272|  background: transparent;
273|  cursor: pointer;
274|  align-items: center;
275|  justify-content: center;
276|}
277|
278|.nav-burger span {
279|  display: block;
280|  width: 16px;
281|  height: 1.5px;
282|  background: var(--text);
283|  position: relative;
284|}
285|
286|.nav-burger span::before,
287|.nav-burger span::after {
288|  content: '';
289|  position: absolute;
290|  left: 0;
291|  width: 16px;
292|  height: 1.5px;
293|  background: var(--text);
294|}
295|
296|.nav-burger span::before { top: -5px; }
297|.nav-burger span::after { top: 5px; }
298|
299|.nav-links.open {
300|  display: flex;
301|  flex-direction: column;
302|  position: absolute;
303|  top: var(--nav-h);
304|  left: 0;
305|  right: 0;
306|  background: rgba(0,0,0,0.96);
307|  backdrop-filter: blur(12px);
308|  -webkit-backdrop-filter: blur(12px);
309|  border-bottom: 1px solid var(--border);
310|  padding: var(--s4) var(--s5);
311|  gap: var(--s4);
312|  z-index: 99;
313|}
314|
315|.nav-links.open a {
316|  color: var(--text);
317|  padding: var(--s3) 0;
318|  border-bottom: 1px solid var(--border);
319|  font-size: var(--text-base);
320|  font-weight: 400;
321|}
322|
323|.nav-links.open a:last-of-type { border-bottom: none; }
324|
325|.nav-burger[aria-expanded="true"] span { background: var(--signal); }
326|.nav-burger[aria-expanded="true"] span::before,
327|.nav-burger[aria-expanded="true"] span::after { background: var(--signal); }
328|
329|/* ============================================
330|   BUTTON
331|   ============================================ */
332|
333|.btn-primary {
334|  display: inline-flex;
335|  align-items: center;
336|  height: 48px;
337|  padding: 0 var(--s6);
338|  background: transparent;
339|  border: 1px solid var(--border-strong);
340|  color: var(--text);
341|  font-size: var(--text-sm);
342|  font-weight: 500;
343|  letter-spacing: -0.01em;
344|  text-decoration: none;
345|  cursor: pointer;
346|  transition: border-color var(--speed) var(--ease),
347|              color var(--speed) var(--ease),
348|              transform var(--speed-fast) var(--ease);
349|  font-family: inherit;
350|  position: relative;
351|}
352|
353|.btn-primary::after {
354|  content: '→';
355|  margin-left: var(--s2);
356|  font-size: calc(var(--text-sm) - 2px);
357|  opacity: 0.6;
358|  transition: opacity var(--speed) var(--ease), transform var(--speed-fast) var(--ease);
359|}
360|
361|.btn-primary:hover {
362|  border-color: var(--signal);
363|  color: var(--signal);
364|  transform: translateY(-1px);
365|}
366|
367|.btn-primary:hover::after {
368|  opacity: 1;
369|  transform: translateX(2px);
370|}
371|
372|.btn-primary:active { transform: scale(0.97); }
373|
374|.btn-primary-lg { height: 54px; padding: 0 var(--s8); font-size: 15px; }
375|
376|/* Ghost variant: border + signal green text */
377|.btn-ghost-primary {
378|  display: inline-flex;
379|  align-items: center;
380|  height: 48px;
381|  padding: 0 var(--s6);
382|  background: transparent;
383|  border: 1px solid var(--border-strong);
384|  color: var(--signal);
385|  font-size: var(--text-sm);
386|  font-weight: 500;
387|  letter-spacing: -0.01em;
388|  text-decoration: none;
389|  cursor: pointer;
390|  transition: border-color var(--speed) var(--ease),
391|              color var(--speed) var(--ease),
392|              transform var(--speed-fast) var(--ease);
393|  font-family: inherit;
394|  position: relative;
395|}
396|
397|.btn-ghost-primary::after {
398|  content: '→';
399|  margin-left: var(--s2);
400|  font-size: calc(var(--text-sm) - 2px);
401|  opacity: 0.6;
402|  transition: opacity var(--speed) var(--ease), transform var(--speed-fast) var(--ease);
403|}
404|
405|.btn-ghost-primary:hover {
406|  border-color: var(--signal);
407|  color: var(--signal-bright);
408|}
409|
410|.btn-ghost-primary:hover::after {
411|  opacity: 1;
412|  transform: translateX(2px);
413|}
414|
415|.btn-ghost-primary:active { transform: scale(0.97); }
416|
417|/* ============================================
418|   HERO
419|   ============================================ */
420|
421|.hero {
422|  min-height: 100vh;
423|  display: flex;
424|  align-items: center;
425|  justify-content: center;
426|  padding: var(--s20) var(--s5);
427|  position: relative;
428|}
429|
430|.hero-inner {
431|  max-width: var(--max-w);
432|  margin: 0 auto;
433|  width: 100%;
434|  text-align: left;
435|}
436|
437|.hero-content {
438|  max-width: 560px;
439|}
440|
441|.hero-label {
442|  font-size: var(--text-xs);
443|  font-weight: 500;
444|  letter-spacing: 0.06em;
445|  text-transform: uppercase;
446|  color: var(--signal);
447|  margin-bottom: var(--s4);
448|}
449|
450|.hero-headline {
451|  font-size: var(--display);
452|  font-weight: 300;
453|  letter-spacing: -0.045em;
454|  line-height: 1.02;
455|  margin-bottom: var(--s6);
456|  text-wrap: balance;
457|}
458|
459|.hero-body {
460|  font-size: var(--text-lg);
461|  color: var(--text-secondary);
462|  line-height: 1.5;
463|  margin-bottom: var(--s8);
464|  max-width: 440px;
465|}
466|
467|.hero-cta-row {
468|  display: flex;
469|  align-items: baseline;
470|  gap: var(--s4);
471|  flex-wrap: wrap;
472|}
473|
474|.hero-cta-sub {
475|  font-size: var(--text-sm);
476|  color: var(--text-tertiary);
477|  letter-spacing: -0.01em;
478|}
479|
480|.hero-mark {
481|  position: relative;
482|  display: flex;
483|  align-items: center;
484|  justify-content: center;
485|  aspect-ratio: 1;
486|  max-width: 480px;
487|  margin-left: auto;
488|}
489|
490|.brand-mark-lg {
491|  width: 60%;
492|  height: auto;
493|}
494|
495|
496|/* ============================================
497|   SHARED — SECTION LABEL + HUMAN BOUND
498|   ============================================ */
499|
500|.section-label {
501|  font-size: var(--text-xs);
502|  font-weight: 500;
503|  letter-spacing: 0.06em;
504|  text-transform: uppercase;
505|  color: var(--signal);
506|  margin-bottom: var(--s4);
507|}
508|
509|.human-bound {
510|  display: flex;
511|  align-items: center;
512|  gap: var(--s4);
513|  padding: var(--s3) var(--s4);
514|  border-left: 2px solid var(--signal);
515|  background: transparent;
516|}
517|
518|.human-label {
519|  font-size: var(--text-xs);
520|  font-weight: 500;
521|  letter-spacing: 0.05em;
522|  text-transform: uppercase;
523|  color: var(--signal);
524|  margin-bottom: 2px;
525|}
526|
527|.human-desc {
528|  font-size: var(--text-sm);
529|  color: var(--text-secondary);
530|  letter-spacing: -0.01em;
531|}
532|
533|/* ============================================
534|   DIFFERENT SECTION
535|   ============================================ */
536|
537|.different {
538|  padding: var(--s20) var(--s5);
539|  border-top: 1px solid var(--border);
540|}
541|
542|.different-inner {
543|  max-width: 720px;
544|  margin: 0 auto;
545|  text-align: left;
546|}
547|
548|.different-headline {
549|  font-size: var(--headline-lg);
550|  font-weight: 300;
551|  letter-spacing: -0.045em;
552|  line-height: 1.1;
553|  margin-bottom: var(--s6);
554|  text-wrap: balance;
555|}
556|
557|.different-twins {
558|  font-size: var(--headline-xl);
559|  font-weight: 300;
560|  letter-spacing: -0.045em;
561|  line-height: 1.05;
562|  margin-bottom: var(--s6);
563|  text-wrap: balance;
564|}
565|
566|
567|.different-points {
568|  display: flex;
569|  flex-direction: column;
570|  gap: var(--s3);
571|}
572|
573|.diff-point {
574|  display: flex;
575|  align-items: baseline;
576|  gap: var(--s4);
577|  padding: var(--s3) 0;
578|  border-bottom: 1px solid var(--border);
579|}
580|
581|.diff-point:last-child { border-bottom: none; }
582|
583|.diff-num {
584|  font-size: var(--text-xs);
585|  font-weight: 500;
586|  color: var(--signal);
587|  letter-spacing: 0.04em;
588|  font-variant-numeric: tabular-nums;
589|  flex-shrink: 0;
590|}
591|
592|.diff-text {
593|  font-size: var(--text-base);
594|  color: var(--text);
595|  letter-spacing: -0.01em;
596|  font-weight: 400;
597|}
598|
599|/* ============================================
600|   HUMAN ARCHITECT
601|   ============================================ */
602|
603|.human-arch {
604|  padding: var(--s24) var(--s5);
605|  border-top: 1px solid var(--border);
606|  border-bottom: 1px solid var(--border);
607|}
608|
609|.human-inner {
610|  max-width: var(--max-w);
611|  margin: 0 auto;
612|  display: grid;
613|  grid-template-columns: 1fr 1fr;
614|  gap: var(--s16);
615|  align-items: center;
616|}
617|
618|.human-content {
619|  max-width: 480px;
620|  text-align: left;
621|}
622|
623|.human-label-lg {
624|  font-size: var(--text-xs);
625|  font-weight: 500;
626|  letter-spacing: 0.06em;
627|  text-transform: uppercase;
628|  color: var(--signal);
629|  margin-bottom: var(--s4);
630|}
631|
632|.human-headline {
633|  font-size: var(--headline-xl);
634|  font-weight: 300;
635|  letter-spacing: -0.045em;
636|  line-height: 1.05;
637|  margin-bottom: var(--s6);
638|  text-wrap: balance;
639|}
640|
641|.human-body {
642|  font-size: var(--text-lg);
643|  color: var(--text-secondary);
644|  line-height: 1.55;
645|  margin-bottom: var(--s4);
646|}
647|
648|.human-mark {
649|  position: relative;
650|  display: flex;
651|  align-items: center;
652|  justify-content: center;
653|  aspect-ratio: 1;
654|  max-width: 320px;
655|  margin-left: auto;
656|}
657|
658|
659|/* ============================================
660|   OFFER / PRICING
661|   ============================================ */
662|
663|.offer {
664|  padding: var(--s16) var(--s5);
665|  border-top: 1px solid var(--border);
666|  text-align: left;
667|}
668|
669|.offer-inner {
670|  max-width: 480px;
671|  margin: 0 auto;
672|}
673|
674|.offer-label {
675|  font-size: var(--text-xs);
676|  font-weight: 500;
677|  letter-spacing: 0.06em;
678|  text-transform: uppercase;
679|  color: var(--signal);
680|  margin-bottom: var(--s4);
681|}
682|
683|.offer-price-row {
684|  display: flex;
685|  align-items: baseline;
686|  justify-content: flex-start;
687|  gap: var(--s2);
688|  margin-bottom: var(--s5);
689|}
690|
691|.offer-price {
692|  font-size: var(--headline-xxl);
693|  font-weight: 300;
694|  letter-spacing: -0.045em;
695|  line-height: 1;
696|  font-variant-numeric: tabular-nums;
697|}
698|
699|.offer-price-sub {
700|  font-size: var(--text-lg);
701|  color: var(--text-tertiary);
702|  letter-spacing: -0.01em;
703|}
704|
705|.offer-body {
706|  font-size: var(--text-lg);
707|  color: var(--text-secondary);
708|  line-height: 1.5;
709|  margin-bottom: var(--s8);
710|}
711|
712|.offer-list {
713|  display: flex;
714|  flex-wrap: wrap;
715|  justify-content: flex-start;
716|  gap: var(--s2) var(--s4);
717|  margin-bottom: var(--s8);
718|}
719|
720|.offer-item {
721|  font-size: var(--text-sm);
722|  color: var(--text-secondary);
723|  letter-spacing: -0.01em;
724|  padding: var(--s1) 0;
725|}
726|
727|.offer-start {
728|  font-size: var(--text-base);
729|  color: var(--text);
730|  letter-spacing: -0.01em;
731|  margin-bottom: var(--s6);
732|}
733|
734|.offer-cta-row {
735|  display: flex;
736|  flex-direction: column;
737|  align-items: flex-start;
738|  gap: var(--s3);
739|}
740|
741|.offer-reassure {
742|  font-size: var(--text-sm);
743|  color: var(--text-tertiary);
744|  letter-spacing: -0.01em;
745|}
746|
747|/* ============================================
748|   STORY SECTION
749|   ============================================ */
750|
751|.story {
752|  padding: var(--s20) var(--s5);
753|  border-top: 1px solid var(--border);
